import { CrumpledPaperReveal, DEFAULT_SHEETS, type PaperSheet } from "@/components/ui/crumpled-paper-reveal"

// "Blue Ridge Mountains" by Ken Thomas, public domain (Wikimedia Commons),
// cropped and graded blue. Embedded so the demo fetches nothing.
const BLUE_RIDGE = "data:image/jpeg;base64,"

const sheets: PaperSheet[] = DEFAULT_SHEETS.map((s) => (s.kind === "photo" ? { ...s, image: BLUE_RIDGE } : s))

export default function Demo() {
  return <CrumpledPaperReveal sheets={sheets} />
}
